import{_ as s,l as d,o as e,c as i,v as r,p as n,x as t,d as l,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"存储过程","description":"","frontmatter":{"title":"存储过程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stored-procedures.md","filePath":"cs/stored-procedures.md","lastUpdated":1789023840000}'),A={name:"cs/stored-procedures.md"};function E(h,a,S,_,u,m){const o=d("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="存储过程" tabindex="-1">存储过程 <a class="header-anchor" href="#存储过程" aria-label="Permalink to &quot;存储过程&quot;">​</a></h1><div class="epigraph"><p>过程把多条 SQL 与控制流放进库内一次调用；少往返，也把优化边界从「一句声明」换成「一段程序」。</p><footer>—— 据 Gray and Reuter 对事务中的过程；Ramakrishnan and Gehrke；SQL/PSM 标准整理</footer></div><p><a href="/cs/constraints-triggers">上一课</a>把触发器定为事件上的过程。本课不重写 ECA。缺口是<strong>显式调用</strong>的库内程序：存储过程与函数，参数进、结果出（或侧效写表）。应用一次 RPC 完成多语句，减少延迟；代价是计划缓存、权限与「优化器看不到循环」同时出现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若业务是「扣库存、写订单、写流水」三条语句，客户端三次往返把锁持有时间拉长。过程在库内顺序执行，同一事务、一次网络。缺口不是再讲 ACID——主干 <a href="/cs/acid">事务</a> 已有——而是过程作为查询接口：它还是声明吗？对优化器，过程体是语句序列加分支循环，一般<strong>不会</strong>把整个过程当成一棵代数树重写。</p><p>函数分为只读标量/表值与含 SQL 的过程函数。纯函数有时能下推；含 SQL 或易失的不能。SQL/PSM、PL/pgSQL、T-SQL 是不同表面，本课只锁定：库内控制流 + SQL 语句 + 事务交界。</p><p><span class="marginnote">存储过程不是「更快的 SQL」。快来自少往返、少解析、计划复用。写坏的过程里逐行循环（RBAR）会比一条集合语句慢几个数量级。集合化仍是默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义：参数模式（IN/OUT）、过程体、执行权限（定义者/调用者）。调用：<code>CALL</code> 或 <code>SELECT fn()</code>。事务：过程默认参加调用方事务；有的产品允许自治事务，本课点名其危险（提交脱离外层）。错误处理：异常处理器决定回滚语句还是整个事务。</p><p>与预编译语句的关系：过程体内的 SQL 仍走解析与计划；后课计划缓存专门讲绑定与老化。本课只要求过程调用是粗粒度 API。</p>',10)),(e(),n(c,null,{default:t(()=>[p(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E5%BA%94%E7%94%A8%E4%B8%80%E6%AC%A1%E8%B0%83%E7%94%A8%22%5D%20--%3E%20SP%5B%22%E5%BA%93%E5%86%85%E8%BF%87%E7%A8%8B%22%5D%0A%20%20SP%20--%3E%20S1%5B%22SQL%20%E8%AF%AD%E5%8F%A5%22%5D%0A%20%20SP%20--%3E%20CTL%5B%22%E5%88%86%E6%94%AF%20%2F%20%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20S1%20--%3E%20TX%5B%22%E5%90%8C%E4%B8%80%E4%BA%8B%E5%8A%A1%22%5D%0A%20%20CTL%20--%3E%20S1%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>权限：授予 <code>EXECUTE</code> 而不授予底层表，可做安全边界——也是 SQL 注入面，若过程用字符串拼 SQL 则退回动态 SQL 风险。确定性：标量函数若声明 IMMUTABLE，优化器可折叠；标错会错结果。</p><p>触发器调用过程：ECA 的 A 可以是过程。仍看不见体内部代数。递归过程与递归 CTE 不是同一层：前者是调用栈，后者是查询不动点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲连接池如何复用会话——再后课。也不把 ORM 的「过程映射」当模型。游标循环在过程里合法，但主干建议能写成集合就不要游标。保存点下一课：过程中的部分回滚。</p><p>后课默认：过程是库内 API 与事务脚本，不是另一套关系代数。查询能一句写完的不要拆成过程里的行循环。</p><p>往返与锁持有时间是过程的性能理由；语义理由是把不变式维护放进与表同一权限域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>存储过程减少往返，把多语句收进一次调用与同一事务。</li><li>优化器通常不把过程体当一棵树；集合 SQL 仍优先。</li><li>保存点下一课：过程与长事务里的部分撤销。</li><li>出处：Gray and Reuter；Ramakrishnan and Gehrke；SQL/PSM。</li></ul>',9))])}const T=s(A,[["render",E]]);export{L as __pageData,T as default};
